hints:
```
create boolean array of size 128, all false
for each character c in jewels:
    array[c] = true
count = 0
for each character c in stones:
    if array[c]:
        count = count + 1
return count
```

code.cpp:
class Solution {
public:
    int numJewelsInStones(string jewels, string stones) {
        bool isJewel[128] = {false};
        for (char c : jewels) {
            isJewel[(int)(unsigned char)c] = true;
        }
        int count = 0;
        for (char c : stones) {
            if (isJewel[(int)(unsigned char)c]) {
                count++;
            }
        }
        return count;
    }
};
